'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/search/md-gb-search-bar.js';
import '@material/web/labs/gb/components/search/md-gb-search-view.js';
import {SearchBarElement} from '@material/web/labs/gb/components/search/search-bar-element.js';
import {SearchViewElement} from '@material/web/labs/gb/components/search/search-view-element.js';

/**
 * A Material Design search bar. Wraps <md-gb-search-bar>.
 * Docs: https://material-web.dev/3.0/components/search/
 */
export const MdSearchBar = createComponent({
  react: React,
  tagName: 'md-gb-search-bar',
  elementClass: SearchBarElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onInput: 'input' as EventName<InputEvent>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
    onSearch: 'search' as EventName<CustomEvent<{value: string}>>,
  },
});

export type MdSearchBarProps = React.ComponentProps<typeof MdSearchBar>;

/**
 * Focused search: suggestions or results opened from a search bar. Wraps <md-gb-search-view>.
 * Docs: https://material-web.dev/3.0/components/search/
 */
export const MdSearchView = createComponent({
  react: React,
  tagName: 'md-gb-search-view',
  elementClass: SearchViewElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onInput: 'input' as EventName<InputEvent>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
    onSearch: 'search' as EventName<CustomEvent<{value: string}>>,
  },
});

export type MdSearchViewProps = React.ComponentProps<typeof MdSearchView>;
